(39, 1, 'Admin Thành Tâm', '🔥 BÁN GẤP ĐẤT TẠI TDP HƯNG NHÂN SÔNG TRÍ - CƠ HỘI VÀNG CHO NHÀ ĐẦU TƯ! 🔥\n\n📍 Vị trí: TDP Hưng Nhân Sông Trí\n📐 Diện tích: 230m2 (7x25m) có 100m2 đất ở\n🌳 Tiện ích: Gần trung tâm, thuận lợi cho sinh hoạt\n📜 Pháp lý: Đầy đủ\n🗺️ Quy hoạch: Rõ ràng, không tranh chấp\n🧭 Phong thủy: Hướng Tây Nam, đón tài lộc\n\nGiá chạm đáy, cắt lỗ nhanh cho khách hàng thiện chí! Đừng bỏ lỡ cơ hội này, liên hệ ngay với chúng tôi để được tư vấn chi tiết. \n\nNhân viên tư vấn: Admin Thành Tâm - SĐT: 0964716776\n\n#BDSThanhTam #NhaDatHaTinh', '[\"/static/uploads/98e04e7192504a62bd427e642a96f65d.jpg\", \"/static/uploads/6ac2028221dc44c19292b1cfe95db332.jpg\"]', 'pending', '2026-10-07 16:41:01', '/static/uploads/072677feadcb4d3bbe1140ede63721b2.mp4'),
(40, 16, 'Nguyễn Thị Thành', '🌟 Cơ hội sở hữu lô đất 2 mặt tiền đắc địa tại TDP Hưng Lợi!\n\nBạn đang tìm kiếm một vị trí lý tưởng cho dự án đầu tư hoặc xây dựng tổ ấm của mình? Với diện tích 230m2, lô đất này tọa lạc tại khu vực trung tâm phát triển sôi động, mang đến tiềm năng sinh lời cao trong tương lai. Pháp lý rõ ràng, quy hoạch đất nền đảm bảo an tâm cho mọi quyết định đầu tư của bạn.\n\n📞 Hãy liên hệ ngay với nhân viên tư vấn Nguyễn Thị Thành qua số điện thoại 0937488234 để biết thêm thông tin chi tiết và sắp xếp lịch xem đất!\n\n#BDSThanhTam #NhaDatHaTinh', '[\"/static/uploads/b07f829d2a1c48f39d0198c795b83e42.jpg\", \"/static/uploads/2c750495167f44e09ec4d3a0157a57f9.jpg\"]', 'pending', '2026-10-09 11:43:46', NULL),
(41, 20, 'Lê Thanh Phương', '🔥 CƠ HỘI BÁN GẤP LÔ ĐẤT 2 MẶT TIỀN TẠI TRƯỜNG LẠC KỲ HOA\n\n📍 Vị trí: Trường Lạc Kỳ Hoa\n📐 Diện tích: 167m2 (7x23m, 100m đất ở)\n🌳 Tiện ích: Gần trung tâm văn hóa xã, thuận tiện đi chợ, đường nhựa rộng 10m\n📜 Pháp lý: Rõ ràng\n🗺️ Quy hoạch: Đất ở nông thôn\n🧭 Phong thủy: Hướng tây nam\n\n🔔 Đừng bỏ lỡ cơ hội này, giá chạm đáy và cắt lỗ cực mạnh! Liên hệ ngay với nhân viên tư vấn Lê Thanh Phương để sở hữu ngay lô đất vàng này!\n\n#BDSThanhTam #NhaDatHaTinh', '[\"/static/uploads/5ebcc5d30f8a46a79c2a3a02021c0f78.jpg\", \"/static/uploads/439ec9b5c8ed44b490a545dd80ef598b.jpg\", \"/static/uploads/eac66dbd5bc0489f8c11addb858826b0.jpg\"]', 'pending', '2026-10-10 10:25:04', NULL);
